import {kind,adjacent,valid,remove,stars,solve} from './engine.js';
import {levels} from './levels.js';
const $=id=>document.getElementById(id);let stage=0,board,moves,history=[],selected=[],dragging=false,moved=false,start=-1,hints=[],sound=false,audio;
let progress={};try{progress=JSON.parse(localStorage.getItem('sequencepang2-v1')||'{}')||{};}catch{}
const modal=$('modal');const mascot=$('mascot');mascot.src='./mango.png';mascot.onload=()=>mascot.hidden=false;
function beep(win=false){if(!sound)return;try{audio??=new AudioContext();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.type='sine';o.frequency.setValueAtTime(win?660:440,audio.currentTime);o.frequency.exponentialRampToValueAtTime(win?1320:880,audio.currentTime+.13);g.gain.setValueAtTime(.08,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.25);o.start();o.stop(audio.currentTime+.26);}catch{}}
function message(s,good=false){$('feedback').textContent=s;$('feedback').classList.toggle('good',good);}
function load(i){stage=i;board=structuredClone(levels[i].board);moves=levels[i].moves;history=[];selected=[];hints=[];dragging=false;modal.close();render();message('숫자 3개 이상을 이어 보세요');}
function render(){const l=levels[stage];$('stage-no').textContent=String(stage+1).padStart(2,'0');$('moves').textContent=moves;$('star-count').textContent=`${stars(l.board)-stars(board)} / ${stars(l.board)}`;$('undo').disabled=!history.length;$('board').style.setProperty('--n',l.n);$('board').innerHTML=board.map((c,i)=>c?`<button class="tile${c.star?' starred':''}" data-i="${i}" aria-label="${Math.floor(i/l.n)+1}행 ${i%l.n+1}열, ${c.v}${c.star?', 별':''}" aria-pressed="false"><span>${c.v}</span>${c.star?'<span class="star" aria-hidden="true">★</span>':''}</button>`:'<div class="empty" aria-hidden="true"></div>').join('');paint();}
function paint(){document.querySelectorAll('.tile').forEach(el=>{const i=+el.dataset.i;el.classList.toggle('selected',selected.includes(i));el.classList.toggle('hinted',hints.includes(i));el.setAttribute('aria-pressed',String(selected.includes(i)));});const shell=$('board').parentElement.getBoundingClientRect();$('lines').querySelector('polyline').setAttribute('points',selected.map(i=>{const e=$('board').querySelector(`[data-i="${i}"]`).getBoundingClientRect();return `${e.x+e.width/2-shell.x},${e.y+e.height/2-shell.y}`;}).join(' '));$('submit').hidden=selected.length<3||dragging;}
function pick(i){if(!board[i]||!moves||!stars(board))return;if(selected.length>1&&selected.at(-2)===i)selected.pop();else if(!selected.includes(i)&&(!selected.length||adjacent(selected.at(-1),i,levels[stage].n)))selected.push(i);hints=[];paint();if(selected.length){const values=selected.map(i=>board[i].v),k=kind(values);message(`${values.join(' · ')}${k?' — '+k:''}`,!!k);}}
function commit(){if(!selected.length)return;const p=selected.slice();selected=[];if(!valid(board,p,levels[stage].n)){paint();message('등차·등비수열 3개 이상을 연결해 주세요');return;}history.push({board:structuredClone(board),moves});board=remove(board,p,levels[stage].n);moves--;hints=[];beep();render();message(`${kind(p.map(i=>history.at(-1).board[i].v))} 팡!`,true);if(!stars(board)){progress[stage]=true;try{localStorage.setItem('sequencepang2-v1',JSON.stringify(progress));}catch{}beep(true);showResult(true);}else if(!moves)showResult(false);}
function show(content){$('modal-content').innerHTML=content;if(!modal.open)modal.showModal();}
function showResult(won){show(`<div class="medal">${won?'★ ★ ★':'↶'}</div><h2>${won?'STAGE CLEAR!':'한 번 더 생각해 볼까요?'}</h2><p>${won?(stage===7?'8개의 스테이지를 모두 끝냈어요!':'별을 모두 모았어요.'):'되돌리기로 다른 수열을 찾아보세요.'}</p><button class="primary" id="result-action">${won?(stage===7?'스테이지 선택':'다음 스테이지'):'되돌리기'}</button>`);$('result-action').onclick=()=>{if(won){if(stage===7)picker();else load(stage+1);}else{modal.close();undo();}};}
function undo(){if(!history.length)return;({board,moves}=history.pop());selected=[];hints=[];render();message('한 수 되돌렸어요');}
function picker(){show('<h2>STAGES</h2><div class="level-grid">'+levels.map((l,i)=>`<button data-stage="${i}" class="${i===stage?'current ':''}${progress[i]?'done':''}">${String(i+1).padStart(2,'0')}<small>${progress[i]?'★':'·'}</small></button>`).join('')+'</div>');$('modal-content').querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>load(+b.dataset.stage));}
$('board').addEventListener('pointerdown',e=>{if(e.button!==0||!e.isPrimary)return;const tile=e.target.closest('[data-i]');if(!tile)return;e.preventDefault();start=+tile.dataset.i;dragging=true;moved=false;selected=[];pick(start);$('board').setPointerCapture(e.pointerId);});
$('board').addEventListener('pointermove',e=>{if(!dragging||!e.isPrimary)return;const tile=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-i]');if(tile&&$('board').contains(tile)){const i=+tile.dataset.i;if(i!==start)moved=true;pick(i);}});
$('board').addEventListener('pointerup',e=>{if(!dragging||!e.isPrimary)return;dragging=false;if(moved)commit();else{selected=[];paint();message('누른 채로 숫자 3개 이상을 이으세요');}});
$('board').addEventListener('pointercancel',()=>{dragging=false;selected=[];paint();message('선택을 취소했어요');});
$('board').addEventListener('click',e=>{if(e.detail!==0)return;const tile=e.target.closest('[data-i]');if(tile)pick(+tile.dataset.i);});
$('board').addEventListener('keydown',e=>{if(e.key==='Escape'){selected=[];paint();}if(e.key==='Enter'&&e.ctrlKey){e.preventDefault();commit();}});
$('submit').onclick=commit;$('undo').onclick=undo;$('restart').onclick=()=>load(stage);$('stage-picker').onclick=picker;$('close-modal').onclick=()=>modal.close();
$('hint').onclick=()=>{selected=[];const solution=solve(board,levels[stage].n,moves);if(solution?.length){hints=solution[0];paint();message('반짝이는 숫자를 순서대로 이으세요: '+hints.map(i=>board[i].v).join(' → '));}else message(stars(board)?'이 상태에서는 어려워요. 한 수 되돌려 보세요.':'별을 모두 모았어요!',!stars(board));};
$('help').onclick=()=>show('<h2>이어 보면, 수열!</h2><p>이웃한 숫자 <b>3개 이상</b>을 누른 채로 이으세요. 대각선도 가능해요.</p><p><b>등차</b>　1 → 3 → 5<br><b>등비</b>　2 → 4 → 8</p><p>남은 횟수 안에 <b>★ 별을 모두</b> 모으면 성공! 숫자가 사라지면 위의 타일이 아래로 내려와요. 새 타일은 생기지 않아요.</p><p>시간제한은 없어요. 잘못 이으면 횟수는 줄지 않고, 되돌리기는 무제한이에요.</p><p>키보드: Tab으로 이동하고 Space로 선택한 다음 ‘선택 완료’를 누르세요.</p>');
$('sound').onclick=()=>{sound=!sound;$('sound').setAttribute('aria-pressed',String(sound));$('sound').setAttribute('aria-label',sound?'소리 끄기':'소리 켜기');$('sound').style.color=sound?'#ffd15b':'';beep();};
window.addEventListener('resize',paint);load(0);
